#include<bits/stdc++.h>
using namespace std;

int main(){
    int N;
    scanf("%d",&N);
    vector<int>par(N+1,0);
    vector<vector<int>>ch(N+1);
    for(int i=2;i<=N;i++){
        scanf("%d",&par[i]);
        ch[par[i]].push_back(i);
    }

    // Find leaves in DFS order (which is 1..N order since tree is given in preorder)
    vector<int>lf, rg; // leftmost and rightmost leaf of subtree
    lf.resize(N+1); rg.resize(N+1);
    vector<int>leaves;
    for(int i=1;i<=N;i++) if(ch[i].empty()) leaves.push_back(i);

    // Each subtree rooted at v will produce a sub-decomposition.
    // The "interface" bag contains: par[v] (if exists), v, leftLeaf[v], rightLeaf[v]
    // (some of these may coincide)

    vector<vector<int>>bags(1); // 1-indexed
    vector<pair<int,int>>tedges;
    // repBag[v] = bag id whose contents include {par[v], v, lf[v], rg[v]}
    vector<int>repBag(N+1,0);

    auto addBag=[&](vector<int>b)->int{
        // deduplicate
        sort(b.begin(),b.end());
        b.erase(unique(b.begin(),b.end()),b.end());
        bags.push_back(b);
        return (int)bags.size()-1;
    };

    for(int v=N;v>=1;v--){
        if(ch[v].empty()){
            lf[v]=rg[v]=v;
            vector<int>bag;
            if(par[v]) bag.push_back(par[v]);
            bag.push_back(v);
            repBag[v]=addBag(bag);
        } else {
            auto&C=ch[v];
            int k=C.size();
            lf[v]=lf[C[0]]; rg[v]=rg[C[k-1]];
            // Build chain: for each child, connect repBag[child] through intermediate bags
            // containing {par[v],v,child,boundary leaves}
            int prev=0;
            for(int i=0;i<k;i++){
                int c=C[i];
                // Bag: par[v], v, c, lf[c], rg[c]
                vector<int>bag;
                if(par[v]) bag.push_back(par[v]);
                bag.push_back(v);
                bag.push_back(c); bag.push_back(lf[c]); bag.push_back(rg[c]);
                int b1=addBag(bag);
                tedges.push_back({repBag[c],b1});
                if(i>0){
                    // ring edge: rg[C[i-1]] -- lf[C[i]]
                    vector<int>bag2;
                    if(par[v]) bag2.push_back(par[v]);
                    bag2.push_back(v);
                    bag2.push_back(rg[C[i-1]]); bag2.push_back(lf[c]);
                    int b2=addBag(bag2);
                    tedges.push_back({prev,b2});
                    tedges.push_back({b2,b1});
                    prev=b1;
                } else {
                    if(prev) tedges.push_back({prev,b1});
                    prev=b1;
                }
            }
            repBag[v]=prev;
        }
    }
    // Wrap-around ring edge: rg[1]--lf[1]
    if(leaves.size()>=2){
        vector<int>bag={lf[1],rg[1]};
        bag.push_back(1);
        int b=addBag(bag);
        tedges.push_back({repBag[1],b});
    }
    int K=(int)bags.size()-1;
    printf("%d\n",K);
    for(int i=1;i<=K;i++){
        printf("%d",(int)bags[i].size());
        for(int x:bags[i]) printf(" %d",x);
        printf("\n");
    }
    for(auto&[a,b]:tedges) printf("%d %d\n",a,b);
}
